#if DEBUG
    import Foundation

    /// PhotosDemoVideo is the one video the demo server can play: a six second gradient of invented colors, with no
    /// sound, made for the demo and kept here as text so that the app has no file to bundle for it. The player is given
    /// the address of a copy in the temporary folder, since a player reads a file or an address, not bytes.
    enum PhotosDemoVideo {
        /// The address of the video, written to the temporary folder the first time it is asked for.
        static func fileURL() -> URL {
            let fileURL = FileManager.default.temporaryDirectory.appendingPathComponent("demo-video.mp4")
            if !FileManager.default.fileExists(atPath: fileURL.path), let data = Data(base64Encoded: base64Text, options: .ignoreUnknownCharacters) {
                try? data.write(to: fileURL)
            }
            return fileURL
        }

